/**
 * @return list<string>
 */
function changed_files(string $root, string $worktree, string $subject): array
{
    $branch = normalize_branch($subject);

    if ($branch !== null && local_branch_exists($root, $branch)) {
        return branch_changed_files($root, $branch);
    }

    if (! is_dir($worktree)) {
        return [];
    }

    return branch_changed_files($worktree, 'HEAD');
}

/**
 * @return list<string>
 */
function branch_changed_files(string $cwd, string $headRef): array
{
    $base = trim(run_git($cwd, ['merge-base', 'main', $headRef])['stdout']);

    if ($base === '') {
        return [];
    }

    $diff = run_git($cwd, ['diff', '--name-only', '--diff-filter=ACMRT', $base, $headRef]);

    if ($diff['exit_code'] !== 0) {
        return [];
    }

    return array_values(array_filter(
        array_map('trim', preg_split('/\R/', $diff['stdout']) ?: []),
        fn (string $path): bool => $path !== '',
    ));
}

/**
 * @param  list<string>  $items
 */
function every(array $items, callable $callback): bool
{
    foreach ($items as $item) {
        if (! $callback($item)) {
            return false;
        }
    }

    return true;
}

function is_markdown_file(string $path): bool
{
    return preg_match('/\.md$/i', $path) === 1;
}

/**
 * Docs-class diffs are satisfied by docs-lint evidence: Markdown anywhere plus
 * non-PHP harness surfaces (.agents/, docs/, harness-signals/, LOOP.md.example).
 */
function is_docs_class_file(string $path): bool
{
    if (is_markdown_file($path)) {
        return true;
    }

    if (is_php_file($path)) {
        return false;
    }

    return str_starts_with($path, '.agents/')
        || str_starts_with($path, 'docs/')
        || str_starts_with($path, 'harness-signals/')
        || $path === 'LOOP.md.example';
}

function is_php_file(string $path): bool
{
    return preg_match('/\.php$/i', $path) === 1;
}

function is_topology_relevant_php_file(string $path): bool
{
    if (! is_php_file($path)) {
        return false;
    }

    if (str_contains('/'.$path, '/tests/')) {
        return false;
    }

    return ! str_starts_with($path, 'apps/docs/');
}

function docs_only_artifact_problem(string $worktree): ?string
{
    $docsLintProblem = quality_gate_artifact_problem($worktree, 'docs-lint', '`composer docs-lint`');
    $qualityCheckProblem = quality_gate_artifact_problem($worktree, 'quality-check', '`composer quality-check`');

    if ($docsLintProblem === null || $qualityCheckProblem === null) {
        return null;
    }

    return $docsLintProblem.'; '.$qualityCheckProblem;
}

function quality_gate_artifact_problem(string $worktree, string $gate, string $label): ?string
{
    $artifact = latest_quality_gate_artifact($worktree, $gate);

    if ($artifact === null) {
        return "{$label} is required, but no latest successful artifact was found for {$gate}";
    }

    $exitCode = artifact_exit_code($artifact);

    if ($exitCode === null) {
        return "{$label} is required, but latest {$gate} artifact has no numeric exit_code";
    }

    if ($exitCode !== 0) {
        return "{$label} is required, but latest {$gate} artifact exited with code {$exitCode}";
    }

    return null;
}

